from scipy.stats import spearmanr
S=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'; px={}
for s in S:
 f=f'{base}/{s}.csv'
 if os.path.exists(f): px[s]=pd.read_csv(f,parse_dates=['date']).set_index('date')['close'].sort_index()
p=pd.DataFrame(px).sort_index(); p=p.loc[:'2027-10-06']; r=p.pct_change()
v=r.rolling(20,min_periods=15).std()
vix=pd.read_csv('../persistent/index_data/VIX.csv',parse_dates=['date']).set_index('date')['close'].sort_index().reindex(p.index).ffill()
vm=vix.rolling(60,min_periods=40).median(); stress=(vix/vm).clip(.5,2)
# One interpretable idea: 5d volatility-normalized reversal, conditioned by macro stress.
basef=(-r.rolling(5,min_periods=5).sum()/v).clip(-8,8)
variants={'plain':basef,'stress_amp':basef*stress.pow(.5),'stress_damp':basef/stress.pow(.5)}
for name,f in variants.items():
 f=f.shift(1).ewm(span=3,min_periods=3,adjust=False).mean()
 rows=[]
 for d in f.index:
  z=pd.concat([f.loc[d],r.shift(-1).loc[d]],axis=1).dropna()
